#==============================================================================
# PokemonEmeraldOmniversePort -- data layer  (GENERATED by tools/gba_pipeline/gba_world, do not
# hand-edit).  Additively registers the species / moves / abilities / wild
# encounters / trainers decoded from Pokemon Emerald OMNIVERSE v3.gba into GameData, without touching
# any PBS file.  Adapted near-verbatim from Mods/AnimeFusionMerge/Bootstrap.rb
# (battle-tested additive-merge pattern: no DATA.clear, skips MessageTypes bulk
# registration -- name/description accessors fall back to the literal hash
# values, except Move#name/#description which need the MessageTypes.set compat
# shim from Mods/000_mod_manager_loader.rb).
#==============================================================================
module GameData
  class TrainerType
    # GameData::TrainerType#name (unlike Species#name) has no fallback to
    # @real_name when MessageTypes::TrainerTypes has no entry for @id_number,
    # and this loader deliberately skips MessageTypes registration.
    def name
      ret = pbGetMessage(MessageTypes::TrainerTypes, @id_number)
      return (ret && !ret.empty?) ? ret : @real_name
    end
  end
end

module GameData
  class Species
    class << self
      # Our species sit above dex 727, so Infinite Fusion's isFusion? proxy
      # ("id_number > 727") misidentifies every one of them as a computed
      # head*727+body fusion and hands them the generic DNA icon.  Route our
      # explicitly-registered species straight to the normal icon lookup;
      # everything else is unchanged.  Chains onto whatever
      # icon_filename_from_pokemon currently is, so it composes with
      # AnimeFusionMerge / DigimonTrials regardless of mod load order.
      alias pokemonemeraldomniverse_orig_icon_filename_from_pokemon icon_filename_from_pokemon
      def icon_filename_from_pokemon(pkmn)
        if pkmn.isFusion? && !pkmn.egg? && defined?(PokemonEmeraldOmniversePortData) &&
           PokemonEmeraldOmniversePortData.added_species.include?(pkmn.species)
          return self.icon_filename(pkmn.species, pkmn.spriteform_head,
                                    pkmn.gender, pkmn.shiny?,
                                    pkmn.shadowPokemon?, pkmn.egg?)
        end
        return pokemonemeraldomniverse_orig_icon_filename_from_pokemon(pkmn)
      end
    end
  end
end

module PokemonEmeraldOmniversePortData
  # pbCompilerEachPreppedLine / pbGetCsvRecord / pbEachFileSection / csvEnumField!
  # etc. are instance methods of module Compiler, not global Kernel methods.
  extend Compiler

  def self.added_species
    @added_species ||= []
  end

  def self.load_moves(path)
    return unless safeExists?(path)
    added = 0
    pbCompilerEachPreppedLine(path) { |line, line_no|
      line = pbGetCsvRecord(line, line_no, [0, "vnssueeuuueiss",
                                            nil, nil, nil, nil, nil, :Type,
                                            ["Physical", "Special", "Status"],
                                            nil, nil, nil, :Target, nil, nil, nil])
      move_number = line[0]
      move_symbol = line[1].to_sym
      next if GameData::Move::DATA[move_number] || GameData::Move::DATA[move_symbol]
      GameData::Move.register({
        :id_number     => move_number,
        :id            => move_symbol,
        :name          => line[2],
        :function_code => line[3],
        :base_damage   => line[4],
        :type          => line[5],
        :category      => line[6],
        :accuracy      => line[7],
        :total_pp      => line[8],
        :effect_chance => line[9],
        :target        => GameData::Target.get(line[10]).id,
        :priority      => line[11],
        :flags         => line[12],
        :description   => line[13]
      })
      MessageTypes.set(MessageTypes::Moves, move_number, line[2]) if line[2]
      MessageTypes.set(MessageTypes::MoveDescriptions, move_number, line[13]) if line[13]
      added += 1
    }
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added} moves")
  end

  # Custom types build_data_layer.py mints for raw ROM type ids beyond the 18
  # confirmed-vanilla Gen3 types (see resolve_type() there). Neutral
  # effectiveness by construction -- no Weaknesses/Resistances/Immunities
  # lines in types.txt, so GameData::Type#initialize defaults all three to
  # [] and effectiveness() falls through to NORMAL_EFFECTIVE_ONE both ways.
  def self.load_types(path)
    return unless safeExists?(path)
    added = 0
    File.open(path, "rb") { |f|
      FileLineData.file = path
      pbEachFileSection(f) { |contents, type_number|
        next if GameData::Type::DATA[type_number]
        next if GameData::Type::DATA[contents["InternalName"].to_sym]
        GameData::Type.register({
          :id        => contents["InternalName"].to_sym,
          :id_number => type_number,
          :name      => contents["Name"]
        })
        added += 1
      }
    }
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added} types (neutral effectiveness)")
  end

  def self.load_abilities(path)
    return unless safeExists?(path)
    added = 0
    pbCompilerEachPreppedLine(path) { |line, line_no|
      line = pbGetCsvRecord(line, line_no, [0, "vnss"])
      ability_number = line[0]
      ability_symbol = line[1].to_sym
      next if GameData::Ability::DATA[ability_number] || GameData::Ability::DATA[ability_symbol]
      GameData::Ability.register({
        :id          => ability_symbol,
        :id_number   => ability_number,
        :name        => line[2],
        :description => line[3]
      })
      added += 1
    }
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added} abilities (no effect handlers)")
  end

  def self.load_species(path)
    return unless safeExists?(path)
    added_symbols = []
    File.open(path, "rb") { |f|
      FileLineData.file = path
      schema = GameData::Species.schema
      pbEachFileSection(f) { |contents, species_number|
        next if GameData::Species::DATA[species_number]
        next if GameData::Species::DATA[contents["InternalName"].to_sym]
        for key in schema.keys
          if nil_or_empty?(contents[key])
            contents[key] = nil
            next
          end
          value = pbGetCsvRecord(contents[key], key, schema[key])
          value = nil if value.is_a?(Array) && value.length == 0
          contents[key] = value
          case key
          when "BaseStats", "EffortPoints"
            value_hash = {}
            GameData::Stat.each_main do |s|
              value_hash[s.id] = value[s.pbs_order] if s.pbs_order >= 0
            end
            contents[key] = value_hash
          when "Height", "Weight"
            contents[key] = (value * 10).round
          when "Moves"
            move_array = []
            for i in 0...value.length / 2
              move_array.push([value[i * 2], value[i * 2 + 1], i])
            end
            move_array.sort! { |a, b| (a[0] == b[0]) ? a[2] <=> b[2] : a[0] <=> b[0] }
            move_array.each { |arr| arr.pop }
            contents[key] = move_array
          when "TutorMoves", "EggMoves", "Abilities", "HiddenAbility", "Compatibility"
            contents[key] = [contents[key]] if !contents[key].is_a?(Array)
            contents[key].compact!
          when "Evolutions"
            evo_array = []
            for i in 0...value.length / 3
              evo_array.push([value[i * 3], value[i * 3 + 1], value[i * 3 + 2], false])
            end
            contents[key] = evo_array
          end
        end
        species_symbol = contents["InternalName"].to_sym
        GameData::Species.register({
          :id                    => species_symbol,
          :id_number             => species_number,
          :name                  => contents["Name"],
          :form_name             => contents["FormName"],
          :category              => contents["Kind"],
          :pokedex_entry         => contents["Pokedex"],
          :type1                 => contents["Type1"],
          :type2                 => contents["Type2"],
          :base_stats            => contents["BaseStats"],
          :evs                   => contents["EffortPoints"],
          :base_exp              => contents["BaseEXP"],
          :growth_rate           => contents["GrowthRate"],
          :gender_ratio          => contents["GenderRate"],
          :catch_rate            => contents["Rareness"],
          :happiness             => contents["Happiness"],
          :moves                 => contents["Moves"],
          :tutor_moves           => contents["TutorMoves"],
          :egg_moves             => contents["EggMoves"],
          :abilities             => contents["Abilities"],
          :hidden_abilities      => contents["HiddenAbility"],
          :wild_item_common      => contents["WildItemCommon"],
          :wild_item_uncommon    => contents["WildItemUncommon"],
          :wild_item_rare        => contents["WildItemRare"],
          :egg_groups            => contents["Compatibility"],
          :hatch_steps           => contents["StepsToHatch"],
          :incense               => contents["Incense"],
          :evolutions            => contents["Evolutions"] || [],
          :height                => contents["Height"],
          :weight                => contents["Weight"],
          :color                 => contents["Color"],
          # GameData::BodyShape.get(nil) raises ArgumentError; the ROM has no
          # body-shape data so pokemon.txt always writes "Shape = Head", but
          # keep the nil-safe fallback too (DigimonTrials precedent).
          :shape                 => GameData::BodyShape.get(contents["Shape"] || :Head).id,
          :habitat               => contents["Habitat"],
          :generation            => contents["Generation"],
          :back_sprite_x         => contents["BattlerPlayerX"],
          :back_sprite_y         => contents["BattlerPlayerY"],
          :front_sprite_x        => contents["BattlerEnemyX"],
          :front_sprite_y        => contents["BattlerEnemyY"],
          :front_sprite_altitude => contents["BattlerAltitude"],
          :shadow_x              => contents["BattlerShadowX"],
          :shadow_size           => contents["BattlerShadowSize"]
        })
        added_symbols.push(species_symbol)
      }
    }
    # Resolve evolution targets/params now every species is loaded, then add
    # reciprocal prevolutions scoped to our own species only (mirrors AFM).
    added_symbols.each do |sym|
      species = GameData::Species.get(sym)
      species.evolutions.each do |evo|
        evo[0] = csvEnumField!(evo[0], :Species, "Evolutions", species.id_number)
        param_type = GameData::Evolution.get(evo[1]).parameter
        if param_type.nil?
          evo[2] = nil
        elsif param_type == Integer
          evo[2] = csvPosInt!(evo[2])
        else
          evo[2] = csvEnumField!(evo[2], param_type, "Evolutions", species.id_number)
        end
      end
    end
    all_evos = {}
    added_symbols.each do |sym|
      GameData::Species.get(sym).evolutions.each do |evo|
        all_evos[evo[0]] = [sym, evo[1], evo[2], true] if !all_evos[evo[0]]
      end
    end
    added_symbols.each do |sym|
      species = GameData::Species.get(sym)
      next if species.evolutions.any? { |evo| evo[3] }
      species.evolutions.push(all_evos[sym].clone) if all_evos[sym]
    end
    @added_species = (@added_species || []) + added_symbols
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added_symbols.length} species")
  end

  # Evolution branches whose SOURCE is an already-registered species (vanilla
  # or another mod).  v1: rom_auto surfaces no Gen3 evo table, so this file is
  # always empty -- the hook is kept so a later evo-decoder pass can drop
  # branches in without a loader change.
  def self.load_extra_evolutions(path)
    return unless safeExists?(path)
    added = 0
    File.readlines(path, chomp: true).each do |line|
      line = line.strip
      next if line.empty?
      src, method_sym, param_str, tgt = line.split(",").map { |p| p.strip }
      src_sym, method_sym, tgt_sym = src.to_sym, method_sym.to_sym, tgt.to_sym
      next unless GameData::Species.exists?(src_sym)
      next unless GameData::Species.exists?(tgt_sym)
      next unless GameData::Evolution.exists?(method_sym)
      species = GameData::Species.get(src_sym)
      next if species.evolutions.any? { |e| e[0] == tgt_sym && e[1] == method_sym }
      pt = GameData::Evolution.get(method_sym).parameter
      param = if pt.nil? || param_str.nil? || param_str.empty? then nil
              elsif pt == Integer then param_str.to_i
              else param_str.to_sym end
      species.evolutions.push([tgt_sym, method_sym, param, false])
      added += 1
    end
    echoln("[PokemonEmeraldOmniversePortData] Added #{added} extra evolution branches")
  end

  #----------------------------------------------------------------------------
  # Wild encounters -- our own new-format text ([map_id] / TypeName /
  # prob,SPECIES,minLv,maxLv), already keyed onto the baked port map ids.
  # Merges additively (no DATA.clear); creates fresh Encounter records for the
  # 70001+ baked maps (which have no vanilla encounter data) and seeds
  # step_chances from each EncounterType's trigger_chance, exactly as the
  # compiler's new-format path does (002_Compiler_CompilePBS.rb:1176).
  #----------------------------------------------------------------------------
  def self.load_encounters(path)
    return unless safeExists?(path)
    current_map = nil
    current_type = nil
    added_maps = 0
    added_slots = 0
    File.readlines(path, chomp: true).each do |line|
      line = line.strip
      next if line.empty?
      if line =~ /^\[(\d+)\]$/
        current_map = $1.to_i
        current_type = nil
        key = sprintf("%s_0", current_map).to_sym
        if !GameData::Encounter::DATA[key] && !GameData::Encounter.exists?(current_map)
          GameData::Encounter.register({
            :id           => key,
            :map          => current_map,
            :version      => 0,
            :step_chances => {},
            :types        => {}
          })
          added_maps += 1
        end
      elsif line =~ /^([A-Za-z0-9_]+)$/ && GameData::EncounterType.exists?($1.to_sym)
        current_type = $1.to_sym
        enc = GameData::Encounter.get(current_map)
        if enc
          tc = GameData::EncounterType.get(current_type).trigger_chance
          enc.step_chances[current_type] ||= tc if tc && tc > 0
        end
      elsif current_map && current_type &&
            line =~ /^(\d+)\s*,\s*([A-Za-z0-9_]+)\s*,\s*(\d+)\s*,\s*(\d+)$/
        enc = GameData::Encounter.get(current_map)
        next unless enc
        enc.types[current_type] ||= []
        enc.types[current_type] << [$1.to_i, $2.to_sym, $3.to_i, $4.to_i]
        added_slots += 1
      end
    end
    echoln("[PokemonEmeraldOmniversePortData] Wild encounters: #{added_maps} new maps, #{added_slots} slots")
  end

  def self.load_trainertypes(path)
    return unless safeExists?(path)
    added = 0
    pbCompilerEachCommentedLine(path) { |line, line_no|
      line = pbGetCsvRecord(line, line_no, [0, "unsUSSSeUS",
                                            nil, nil, nil, nil, nil, nil, nil, {
                                              "Male" => 0, "M" => 0, "0" => 0,
                                              "Female" => 1, "F" => 1, "1" => 1,
                                              "Mixed" => 2, "X" => 2, "2" => 2, "" => 2
                                            }, nil, nil])
      type_number = line[0]
      type_symbol = line[1].to_sym
      next if GameData::TrainerType::DATA[type_number] || GameData::TrainerType::DATA[type_symbol]
      GameData::TrainerType.register({
        :id_number   => type_number,
        :id          => type_symbol,
        :name        => line[2],
        :base_money  => line[3],
        :battle_BGM  => line[4],
        :victory_ME  => line[5],
        :intro_ME    => line[6],
        :gender      => line[7],
        :skill_level => line[8],
        :skill_code  => line[9]
      })
      added += 1
    }
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added} trainer types")
  end

  GENDER_TOKEN_MAP = { "M" => 0, "m" => 0, "Male" => 0, "0" => 0,
                       "F" => 1, "f" => 1, "Female" => 1, "1" => 1 }

  def self.load_trainers(path, id_number_base: 16600000)
    return unless safeExists?(path)
    lines = File.readlines(path, chomp: true)
    trainers = []
    current = nil
    current_pkmn = nil
    lines.each do |raw|
      line = raw.sub(/\s*#.*$/, "").strip
      next if line.empty?
      if line =~ /^\[\s*(.+?)\s*\]$/
        trainers << current if current
        parts = $1.split(",").map { |p| p.strip }
        current = {
          :trainer_type => parts[0].to_sym,
          :name => parts[1],
          :version => (parts[2] && parts[2] != "") ? parts[2].to_i : 0,
          :pokemon => []
        }
        current_pkmn = nil
        next
      end
      next unless current
      next unless line =~ /^(\w+)\s*=\s*(.*)$/
      prop = $1
      val = $2.strip
      if prop == "Pokemon"
        fields = val.split(",").map { |p| p.strip }
        current_pkmn = { :species => fields[0].to_sym, :level => fields[1].to_i }
        current[:pokemon].push(current_pkmn)
        next
      end
      next unless current_pkmn
      case prop
      when "Item"    then current_pkmn[:item] = val.to_sym
      when "Moves"   then current_pkmn[:moves] = val.split(",").map { |m| m.strip.to_sym }
      when "Ability" then current_pkmn[:ability] = val.to_sym
      when "Gender"  then current_pkmn[:gender] = GENDER_TOKEN_MAP[val] if GENDER_TOKEN_MAP.key?(val)
      when "Nature"  then current_pkmn[:nature] = val.to_sym
      end
    end
    trainers << current if current

    added = 0
    skipped = 0
    trainers.each_with_index do |t, i|
      next if t[:pokemon].empty?
      if GameData::Trainer.exists?(t[:trainer_type], t[:name], t[:version])
        skipped += 1
        next
      end
      t[:id] = [t[:trainer_type], t[:name], t[:version]]
      t[:id_number] = id_number_base + i
      GameData::Trainer.register(t)
      added += 1
    end
    echoln("[PokemonEmeraldOmniversePortData] Registered #{added} trainers (#{skipped} key collisions skipped)")
  end

  def self.install
    load_types(File.join(__dir__, "types.txt"))
    load_abilities(File.join(__dir__, "abilities.txt"))
    load_moves(File.join(__dir__, "moves.txt"))
    load_species(File.join(__dir__, "pokemon.txt"))
    load_extra_evolutions(File.join(__dir__, "extra_evolutions.txt"))
    load_encounters(File.join(__dir__, "encounters.txt"))
    load_trainertypes(File.join(__dir__, "trainertypes.txt"))
    load_trainers(File.join(__dir__, "trainers.txt"))
  end

  # GameData.load_all runs twice at boot and rebuilds each GameData::*::DATA
  # hash wholesale.  Our script-time install() registrations of species /
  # moves / abilities / trainers persist (they land after both boot load_all
  # calls -- managed mods load last), but a rebuilt GameData::Encounter::DATA
  # would silently drop the 70001+ maps we add here (they are in no PBS), so
  # re-run just load_encounters after every load_all (AFM's proven pattern --
  # scoped to encounters, re-adding the rest is needless risk).
  def self.reload_encounters_after_game_data_load
    load_encounters(File.join(__dir__, "encounters.txt"))
  end
end

PokemonEmeraldOmniversePortData.install

module GameData
  class << self
    alias pokemonemeraldomniverse_original_load_all load_all
    def load_all
      pokemonemeraldomniverse_original_load_all
      PokemonEmeraldOmniversePortData.reload_encounters_after_game_data_load
    end
  end
end
